def contact_label(value):
    if value is None:
        return None
    return value.strip()

import unittest
from formatter import contact_label

class LabelTests(unittest.TestCase):
    def test_none(self):
        self.assertIsNone(contact_label(None))
    def test_trim(self):
        self.assertEqual("Ada", contact_label("  Ada  "))
    def test_case(self):
        self.assertEqual("ADA", contact_label("ADA"))

if __name__ == "__main__":
    unittest.main()
